for k,o in x.items():
 i=int(k);status,review,attempt,gap,cost=notes[i];a=o['source_url'].rsplit('/',1)[-1];files=sorted(p for p in (D/'sources').glob(a+'*receipt.json'))
 results[k]={**o,'outcome':status,'credit':0,'candidate':False,'review_depth':'literal record; historical-index search; primary definitions and selected theorem/conjecture passages; bounded literature and live registry path screen','source_review':review,'mathematical_attempts':attempt,'remaining_lemmas_or_barriers':gap,'lean_cost':cost,'literal_lean_endpoint':None,'source_receipts':[{'path':str(p.relative_to(D)),'receipt_sha256':sha(p.read_bytes()),'http':json.loads(p.read_text())} for p in files],'history':'history-matches.txt and history-filtered.txt; no earlier mathematical exclusion for these exact IDs located, apart from the current assignment mention. Incidental hash substrings discarded.','registry_limit':'Lean Pool complete current path tree; OpenAI recursive root truncated, separate preprints tree and overview fetched; Omega recursive tree truncated. A path-name screen is not a repository-wide semantic proof search or global novelty clearance.','coverage_limit':'No exhaustive literature/citation census; no claim all source proof bodies or figure geometry were audited; zero qualified new endpoints.'}
